import React from 'react';
import clsx from 'clsx';
import './AcidForm.css';

export interface AcidFormFieldProps {
    label?: string;
    description?: string;
    error?: string;
    required?: boolean;
    children: React.ReactNode;
    className?: string;
}

export interface AcidFormProps extends React.FormHTMLAttributes<HTMLFormElement> {
    children: React.ReactNode;
    className?: string;
    gap?: 'sm' | 'md' | 'lg';
}

export const AcidFormField = ({
    label,
    description,
    error,
    required,
    children,
    className
}: AcidFormFieldProps) => (
    <div className={clsx('ac-form-field', error && 'ac-form-field-error', className)}>
        {label && (
            <label className="ac-form-label">
                {label}
                {required && <span className="ac-form-required">*</span>}
            </label>
        )}
        {description && <p className="ac-form-description">{description}</p>}
        <div className="ac-form-control">{children}</div>
        {error && <p className="ac-form-error">{error}</p>}
    </div>
);

export const AcidForm = ({ children, className, gap = 'md', ...props }: AcidFormProps) => (
    <form className={clsx('ac-form', `ac-form-gap-${gap}`, className)} {...props}>
        {children}
    </form>
);

.ac-form {
    display: flex;
    flex-direction: column;
    width: 100%;
}

.ac-form-gap-sm {
    gap: 0.75rem;
}

.ac-form-gap-md {
    gap: 1.5rem;
}

.ac-form-gap-lg {
    gap: 2.5rem;
}

.ac-form-field {
    display: flex;
    flex-direction: column;
    gap: 0.375rem;
    width: 100%;
}

.ac-form-label {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 600;
    letter-spacing: 0.1em;
    color: var(--ac-text-primary);
    text-transform: uppercase;
    display: flex;
    align-items: center;
    gap: 4px;
}

.ac-form-required {
    color: var(--ac-brand);
    font-size: 0.9rem;
}

.ac-form-description {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    color: var(--ac-text-muted);
    line-height: 1.4;
    margin: 0;
}

.ac-form-control {
    width: 100%;
}

.ac-form-error {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    color: var(--ac-brand);
    margin: 0;
    display: flex;
    align-items: center;
    gap: 0.4rem;
}

.ac-form-field-error .ac-form-error::before {
    content: '!';
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 14px;
    height: 14px;
    border-radius: 50%;
    background: var(--ac-brand);
    color: #fff;
    font-size: 0.65rem;
    font-weight: 700;
    flex-shrink: 0;
}
